'use strict';

const node_path = require('node:path');
const casePolice = require('case-police');
const synckit = require('synckit');
const dirs = require('./dirs.cjs');
require('node:url');

const version = "2.2.1";

const recommendedConfig = [
  {
    name: "case-police/setup",
    plugins: {
      get "case-police"() {
        return plugin;
      }
    }
  },
  {
    name: "case-police/rules",
    files: ["**/*.?([cm])[jt]s?(x)"],
    rules: {
      "case-police/string-check": "warn"
    }
  }
];

function createRule({
  create,
  defaultOptions,
  meta
}) {
  return {
    create: ((context) => {
      const optionsWithDefault = context.options.map((options, index) => {
        return {
          ...defaultOptions?.[index] || {},
          ...options || {}
        };
      });
      return create(context, optionsWithDefault);
    }),
    defaultOptions,
    meta
  };
}
function createEslintRule({
  name,
  meta,
  ...rule
}) {
  return createRule({
    meta: {
      ...meta,
      docs: meta.docs
    },
    ...rule
  });
}

const RULE_NAME = "string-check";
const loadDict = synckit.createSyncFn(node_path.join(dirs.distDir, "worker-load.cjs"));
const defaultOptions = {
  noDefault: false,
  dict: {},
  presets: [],
  ignore: []
};
const stringCheck = createEslintRule({
  name: RULE_NAME,
  meta: {
    type: "suggestion",
    docs: {
      description: "make the case correct in string"
    },
    fixable: "code",
    schema: [
      {
        type: "object",
        additionalProperties: false,
        properties: {
          dict: {
            description: "Custom dictionary, will be merged with original dict.",
            type: "object",
            default: {}
          },
          noDefault: {
            description: "Disable the default dictionary.",
            type: "boolean",
            default: false
          },
          presets: {
            description: "Filter the default presets.",
            type: "array",
            default: []
          },
          ignore: {
            description: "Ignore some words.",
            type: "array",
            default: []
          }
        }
      }
    ],
    messages: {
      CasePoliceError: "'{{ from }}' should be '{{ to }}'."
    }
  },
  defaultOptions: [defaultOptions],
  create: (context) => {
    const options = {
      ...defaultOptions,
      ...context.options[0]
    };
    const dict = loadDict(options);
    const code = context.sourceCode.text;
    const extension = node_path.extname(context.filename);
    const isMarkdown = extension === ".md" || extension === ".mdx";
    const checkText = (node) => {
      const start = node.range[0];
      const end = node.range[1];
      const originalStr = code.slice(start, end);
      const outputs = [];
      casePolice.replaceCore(originalStr, dict, options.ignore, (_, index, from, to) => {
        outputs.push({ index, from, to });
      });
      for (const { from, to, index } of outputs) {
        const loc = {
          ...node.loc.start
        };
        for (let i = 0; i < index; i++) {
          if (originalStr[i] === "\n") {
            loc.line++;
            loc.column = 0;
          } else {
            loc.column++;
          }
        }
        context.report({
          messageId: "CasePoliceError",
          data: { from, to },
          node,
          *fix(fixer) {
            yield fixer.replaceTextRange([start + index, start + index + from.length], to);
          },
          loc: {
            start: loc,
            end: {
              line: loc.line,
              column: loc.column + from.length
            }
          }
        });
      }
    };
    const scriptVisitor = {
      Literal: (node) => {
        if (typeof node.value === "string")
          checkText(node);
      },
      JSXText: (node) => {
        checkText(node);
      },
      TemplateElement: (node) => {
        checkText(node);
      },
      Program: (node) => {
        if (isMarkdown)
          checkText(node);
      }
    };
    const templateBodyVisitor = {
      VText(node) {
        checkText(node);
      }
    };
    if (context.sourceCode.parserServices == null || context.sourceCode.parserServices?.defineTemplateBodyVisitor == null)
      return scriptVisitor;
    else
      return context.sourceCode.parserServices?.defineTemplateBodyVisitor(templateBodyVisitor, scriptVisitor);
  }
});

const plugin = {
  meta: {
    name: "case-police",
    version
  },
  rules: {
    "string-check": stringCheck
  },
  configs: {
    // @ts-expect-error TS is complaining about `value` not being the correct type but it is
    recommended: recommendedConfig
  }
};

module.exports = plugin;
